module.exports = function(RED) {
    "use strict";

    var caps = require("./lib/meo-caps");

    // 0 is not a real capability, so it is free as the "any" wildcard.
    var ANY_CAP = 0;

    function MeoEventNode(n) {
        RED.nodes.createNode(this, n);
        var node = this;
        node.gateway = RED.nodes.getNode(n.gateway);
        node.device = n.device;
        node.cap = Number(n.cap) || ANY_CAP;

        if (!node.gateway) {
            node.status({ fill: "red", shape: "ring", text: "node-red:meo.errors.noGateway" });
            return;
        }
        if (!node.device) {
            node.status({ fill: "red", shape: "ring", text: "node-red:meo.errors.noDevice" });
            return;
        }

        // The subscription is shared by every event node, so filtering is ours.
        node.onDeviceEvent = function(deviceId, cap, value) {
            if (deviceId !== node.device) { return; }
            if (node.cap !== ANY_CAP && cap !== node.cap) { return; }

            var label = caps.labelOf(cap);
            node.send({
                // Unrounded: a float32 widened to a double prints long, but
                // that is the value the device actually sent.
                payload: value,
                // Capability label, not the MQTT topic — flows never see topics.
                topic: label,
                deviceId: deviceId,
                cap: cap
            });
            node.status({ fill: "green", shape: "dot", text: label + ": " + display(value) });
        };

        node.gateway.registerListener(node);

        node.on("close", function(removed, done) {
            node.gateway.deregisterListener(node, done);
        });
    }

    // Status text only; msg.payload keeps the exact value.
    function display(value) {
        return String(Number(value.toFixed(3)));
    }

    RED.nodes.registerType("meo-event", MeoEventNode);
};
